def validate_mana_skill_definition(skill: Mapping[str, Any]) -> dict[str, Decimal]:
    """Validate and normalize the future hybrid-cost contract of one Mana skill."""
    if not isinstance(skill, Mapping):
        raise ManaPolicyError("skill must be a mapping")
    if str(skill.get("cost_type") or "") != "mana":
        raise ManaPolicyError("skill cost_type must be 'mana'")
    missing = [
        field for field in (MANA_COST_FLAT_FIELD, MANA_COST_MAX_MP_PERCENT_FIELD)
        if field not in skill
    ]
    if missing:
        raise ManaPolicyError("missing Mana cost fields: " + ", ".join(missing))
    normalized = {
        MANA_COST_FLAT_FIELD: _non_negative_decimal(
            skill[MANA_COST_FLAT_FIELD], MANA_COST_FLAT_FIELD
        ),
        MANA_COST_MAX_MP_PERCENT_FIELD: _non_negative_decimal(
            skill[MANA_COST_MAX_MP_PERCENT_FIELD], MANA_COST_MAX_MP_PERCENT_FIELD
        ),
    }
    if MANA_RESTORE_MAX_MP_PERCENT_FIELD in skill:
        normalized[MANA_RESTORE_MAX_MP_PERCENT_FIELD] = _non_negative_decimal(
            skill[MANA_RESTORE_MAX_MP_PERCENT_FIELD],
            MANA_RESTORE_MAX_MP_PERCENT_FIELD,
        )
    return normalized

def calculate_mana_restore_amount(max_mp: Any, percent: Any) -> int:
    """Return a clamped nominal percentage restoration amount."""
    maximum = _non_negative_int(max_mp, "max_mp")
    restore_percent = _non_negative_decimal(percent, "percent")
    amount = round_mana_value(Decimal(maximum) * restore_percent / Decimal("100"))
    return min(maximum, amount)

def calculate_post_combat_mp_floor(
    max_mp: Any,
    percent: Any = MANA_POST_COMBAT_FLOOR_CURRENT_PERCENT,
) -> int:
    """Return the active canonical 50% post-combat Mana floor."""
    return calculate_mana_restore_amount(max_mp, percent)

def apply_post_combat_mp_floor_value(
    current_mp: Any,
    max_mp: Any,
    percent: Any = MANA_POST_COMBAT_FLOOR_CURRENT_PERCENT,
) -> int:
    """Apply a floor without adding it and without exceeding Max MP."""
    maximum = _non_negative_int(max_mp, "max_mp")
    current = min(_non_negative_int(current_mp, "current_mp"), maximum)
    return max(current, calculate_post_combat_mp_floor(maximum, percent))

def calculate_passive_mp_regen_per_full_minute(max_mp: Any) -> int:
    """Return the unchanged 30% per-full-minute passive regeneration tick."""
    return calculate_mana_restore_amount(max_mp, MANA_REGEN_PERCENT_PER_FULL_MINUTE)

def _calculate_crit_chance_with_soft_cap(total_stat):
    stat = float(total_stat or 0)
    if stat <= CRIT_SOFT_CAP_TRANSITION_STAT:
        return CRIT_BASE_CHANCE + max(0.0, stat - CRIT_STAT_BASELINE) * CRIT_PER_STAT
    excess = stat - CRIT_SOFT_CAP_TRANSITION_STAT
    return CRIT_SOFT_CAP_TRANSITION_CHANCE + CRIT_SOFT_CAP_RANGE * excess / (excess + CRIT_SOFT_CAP_K)

def calculate_dodge_chance(defender_dex, attacker_dex):
    dex_delta = float(defender_dex or 0) - float(attacker_dex or 0)
    if dex_delta <= -20.0:
        return DODGE_MIN_CHANCE
    if dex_delta <= DODGE_SOFT_CAP_TRANSITION_DELTA:
        return DODGE_BASE_CHANCE + dex_delta * DODGE_PER_DEX_DELTA
    excess = dex_delta - DODGE_SOFT_CAP_TRANSITION_DELTA
    return DODGE_SOFT_CAP_TRANSITION_CHANCE + DODGE_SOFT_CAP_RANGE * excess / (excess + DODGE_SOFT_CAP_K)

def calculate_base_max_hp(level, total_stamina):
    """Return base max HP before percentage modifiers such as armor refine."""
    safe_level = max(1, int(level or DEFAULT_STARTING_LEVEL))
    safe_stamina = max(0, int(total_stamina or 0))
    return max(1, STARTING_HP_BASE + safe_level * HP_PER_LEVEL + safe_stamina * HP_PER_STAMINA)

def calculate_priest_heal_amount(max_hp):
    """Return the amount used by the activation heal and both delayed ticks."""
    return max(5, int(round(max(1, int(max_hp)) * 0.10)))

def validate_class_scaling(candidate: Mapping[str, Mapping[str, Mapping[str, object]]]) -> None:
    if set(candidate) != set(SUPPORTED_CLASSES):
        raise ValueError("candidate must define exactly the six supported classes")
    for class_key in SUPPORTED_CLASSES:
        entry = candidate[class_key]
        if set(entry) != {"patk", "matk"}:
            raise ValueError(f"{class_key} must define patk and matk")
        for attack_kind in ("patk", "matk"):
            coefficients = entry[attack_kind]
            if not coefficients:
                raise ValueError(f"{class_key}.{attack_kind} must not be empty")
            for stat_name, coefficient in coefficients.items():
                if stat_name not in SUPPORTED_STATS:
                    raise ValueError(f"unsupported stat: {stat_name}")
                _number(coefficient, f"{class_key}.{attack_kind}.{stat_name}")

def _calculate_attack(
    class_key: object,
    stats: Mapping[str, object],
    attack_kind: str,
    candidate: Mapping[str, Mapping[str, Mapping[str, object]]],
) -> int:
    validate_class_scaling(candidate)
    normalized = normalize_class_key(class_key)
    if normalized not in candidate:
        identity_stat = "str" if attack_kind == "patk" else "int"
        return round_stat(_number(stats.get(identity_stat, 0), identity_stat))
    total = 0.0
    for stat_name, coefficient in candidate[normalized][attack_kind].items():
        total += _number(stats.get(stat_name, 0), stat_name) * _number(coefficient, f"coefficient.{stat_name}")
    return max(0, round_stat(total))

def calc_max_hp_parity(level: object, total_sta: object, refine_percent: object = 0.0) -> int:
    from data.player_hp import calculate_base_max_hp
    base_hp = calculate_base_max_hp(round_stat(level), round_stat(total_sta))
    multiplier = 1.0 + _number(refine_percent, "refine_percent") / 100.0
    return max(1, round_stat(base_hp * multiplier))

def calc_pdef_parity(item_pdef: object, total_sta: object) -> int:
    from data.defense_policy import calculate_total_defense
    return int(calculate_total_defense(_number(item_pdef, "item_pdef"), _number(total_sta, "total_sta")))

def calc_mdef_parity(item_mdef: object, total_wis: object) -> int:
    from data.defense_policy import calculate_total_defense
    return int(calculate_total_defense(_number(item_mdef, "item_mdef"), _number(total_wis, "total_wis")))

def validate_stat_system_config() -> tuple[str, ...]:
    problems = []
    expected_classes = set(SUPPORTED_CLASSES)
    expected_stats = set(PRIMARY_STAT_KEYS)
    for label, matrix in (
        ("PHYSICAL_ATTACK_SCALING", PHYSICAL_ATTACK_SCALING),
        ("MAGICAL_ATTACK_SCALING", MAGICAL_ATTACK_SCALING),
    ):
        if set(matrix) != expected_classes:
            problems.append(f"{label}: class set mismatch")
        for class_key, coefficients in matrix.items():
            if set(coefficients) != expected_stats:
                problems.append(f"{label}/{class_key}: stat key mismatch")
            for stat_key, value in coefficients.items():
                if isinstance(value, bool) or not isinstance(value, (int, float)):
                    problems.append(f"{label}/{class_key}/{stat_key}: coefficient must be numeric")
                elif not math.isfinite(float(value)) or float(value) < 0:
                    problems.append(f"{label}/{class_key}/{stat_key}: coefficient must be finite and non-negative")
    if set(MAX_MP_SCALING) != {"base", "level", "int", "wis"}:
        problems.append("MAX_MP_SCALING: key mismatch")
    for key, value in MAX_MP_SCALING.items():
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            problems.append(f"MAX_MP_SCALING/{key}: coefficient must be numeric")
        elif not math.isfinite(float(value)) or float(value) < 0:
            problems.append(f"MAX_MP_SCALING/{key}: coefficient must be finite and non-negative")
    return tuple(problems)

